+export async function hunt(bot: any, sdk: any, pattern: RegExp, ms = 40000, highest = false) {
+  await bot.dismissBlockingUI();
+  const candidates = sdk.getNearbyNpcs().filter((n: any) => pattern.test(n.name) && n.hp !== 0);
+  if (highest) candidates.sort((a: any, b: any) => b.combatLevel - a.combatLevel || a.distance - b.distance);
+  const n = highest ? candidates[0] : candidates.sort((a: any,b: any)=>Number(b.reachable)-Number(a.reachable)||a.distance-b.distance)[0];
+  if (!n) { console.log('Missing', String(pattern)); return false; }
+  const life = sdk.getState().player.lifeId;
+  const result = await bot.attack(n);
+  if (!result.success) { console.log(result); return false; }
+  let damaged = false;
+  const end = Math.min(Date.now() + ms, Date.parse('2026-10-24T23:58:11.117Z'));
+  while (Date.now() < end) {
+    await bot.dismissBlockingUI();
+    const p = sdk.getState().player, t = sdk.getNearbyNpc(n.index);
+    if (p.lifeId !== life || p.isDead) { console.log('DIED',n.name); return false; }
+    if (t?.hp !== null && t?.hp < t?.maxHp) damaged = true;
+    if (t?.hp === 0 || (damaged && !t && p.combat.targetIndex === -1)) {
+      const g = globalThis as any;
+      g.kills ||= {};
+      g.kills[n.name] = Math.max(g.kills[n.name] || 0, n.combatLevel);
+      console.log('KILL', n.name, n.combatLevel);
+      await sdk.waitForTicks(3);
+      return true;
+    }
+    if(p.hp < Math.max(6,p.maxHp*.45)) {
+      const food = sdk.getInventory().find((i:any)=>i.options?.some((o:string)=>/^eat$/i.test(o)));
+      if(food) await bot.eatFood(food);
+    }
+    if(p.combat.targetIndex === -1 && t && t.hp !== 0) await bot.attack(t);
+    await sdk.waitForTicks(2);
+  }
+  console.log('TIMEOUT',n.name);
+  return false;
+}
+
+export async function style(sdk: any, skill: string) {
+  const s = sdk.getState().combatStyle.styles.find((s:any)=>s.trainsSkills.includes(skill));
+  if(s) { await sdk.sendSetCombatStyle(s.index); await sdk.waitForTicks(2); }
+}
*** End Patch

